/*
 * Д-38. Заявление судебному приставу о сохранении доходов в размере прожиточного минимума.
 * Основа: ч. 5.1 ст. 69 Закона № 229-ФЗ (заявление в подразделение, где ведётся ИП; ПМ трудоспособного населения в
 * целом по РФ или ПМ субъекта для соответствующей социально-демографической группы, если он больше), ч. 5.2 ст. 69
 * (иждивенцы — больше ПМ только через суд), ч. 1.1 ст. 99 (удержание с сохранением ПМ), ч. 3.1 ст. 99 (не действует
 * при алиментах, возмещении вреда здоровью, по потере кормильца, ущерба от преступления), ч. 6 ст. 8 (ПМ сохраняется
 * только на одном счёте), ч. 5 ст. 64.1 (рассмотрение за 10 дней). ПМ на 2026 год — 426-ФЗ (assets/common.js, C.PM).
 * Статус: ЧЕРНОВИК, не проверен юристом.
 */
(function (global) {
  "use strict";
  const { U } = global.Engine;
  const C = global.Common;
  const F = U.F;

  const GROUP = { working: "трудоспособного населения", pension: "пенсионеров", child: "детей" };

  function derive(a) {
    const regional = typeof a.region_pm === "number" && a.region_pm > C.PM.working ? a.region_pm : null;
    return { pm: regional || C.PM.working, regional, excluded: ["alimony", "harm"].includes(a.what) };
  }

  const spec = {
    id: "d38",
    code: "Д-38",
    title: "Заявление приставу о сохранении прожиточного минимума",
    lead: "Пристав списывает всё с карты или зарплаты. По заявлению каждый месяц на одном счёте будет оставаться сумма не меньше прожиточного минимума. Займёт около 5 минут.",
    status: "draft",

    steps: [
      {
        id: "ip", title: "Производство",
        questions: [
          ...C.ipQuestions(),
          { id: "what", type: "choice", label: "Что с вас взыскивают?", options: [
            { value: "debt", label: "Долг: кредит, ЖКХ, налоги, штрафы и т. п." },
            { value: "alimony", label: "Алименты" },
            { value: "harm", label: "Возмещение вреда здоровью, по потере кормильца или ущерба от преступления" },
          ] },
        ],
      },
      {
        id: "money", title: "Доходы и счёт",
        questions: [
          { id: "income", type: "multi", label: "Какие у вас доходы?", options: [
            { value: "salary", label: "Зарплата" },
            { value: "pension", label: "Пенсия" },
            { value: "other", label: "Другие доходы" },
          ] },
          { id: "group", type: "choice", label: "К какой группе вы относитесь?", hint: "От этого зависит, какой прожиточный минимум региона сравнивать с федеральным", options: [
            { value: "working", label: "Трудоспособное население" },
            { value: "pension", label: "Пенсионер" },
          ] },
          { id: "region", type: "text", label: "Регион, где вы живёте", placeholder: "г. Москва" },
          { id: "region_pm", type: "money", label: "Прожиточный минимум в вашем регионе для вашей группы на 2026 год", suffix: "₽", required: false,
            hint: `Если он больше федерального (${U.money(C.PM.working)} ₽), сохраняют региональный. Например, в Москве для трудоспособных — 28 940 ₽. Не знаете — оставьте пустым` },
          { id: "bank", type: "text", label: "Банк, где сохранять деньги", placeholder: "ПАО Сбербанк" },
          { id: "bank_address", type: "text", label: "Адрес банка или отделения", required: false },
          { id: "bik", type: "text", label: "БИК банка", placeholder: "044525225", validate: v => /^\d{9}$/.test(String(v).trim()) ? null : "БИК — 9 цифр" },
          { id: "account", type: "text", label: "Номер счёта", hint: "20 цифр — в приложении банка в реквизитах счёта. Номер карты не подходит", placeholder: "40817810…",
            validate: v => /^\d{20}$/.test(String(v).replace(/\s/g, "")) ? null : "Номер счёта — 20 цифр" },
        ],
      },
      {
        id: "you", title: "Вы",
        questions: [
          { id: "buyer_name", type: "text", label: "Ваши фамилия, имя и отчество", autocomplete: "name" },
          { id: "buyer_birth", type: "date", label: "Дата рождения" },
          { id: "citizenship", type: "text", label: "Гражданство", placeholder: "Российская Федерация" },
          { id: "passport", type: "text", label: "Паспорт: серия, номер, кем и когда выдан", hint: "Закон требует указать документ. Данные остаются в вашем браузере", placeholder: "45 12 345678, выдан ГУ МВД России по г. Москве 01.02.2020" },
          { id: "buyer_address", type: "text", label: "Адрес места жительства", autocomplete: "street-address" },
          { id: "buyer_phone", type: "tel", label: "Телефон", autocomplete: "tel" },
          { id: "buyer_email", type: "email", label: "Электронная почта", required: false, autocomplete: "email" },
        ],
      },
    ],

    derive,

    stop(a, d) {
      if (d.excluded) return { title: "По этому взысканию прожиточный минимум не сохраняется.", text: "Закон не применяет это правило к алиментам, возмещению вреда здоровью, по потере кормильца и ущерба от преступления (ч. 3.1 ст. 99 Закона об исполнительном производстве). Удержать из зарплаты могут не больше 70%. Если на жизнь не остаётся денег, можно просить суд уменьшить размер удержаний — с этим лучше к юристу." };
      return null;
    },

    render(a, d) {
      const P = [];
      const T = t => P.push({ text: t, indent: true });
      C.fsspHeader(P, a, `Судебному приставу-исполнителю ${F(a.bailiff, "ФИО пристава")}`);
      C.title(P, "ЗАЯВЛЕНИЕ", "о сохранении заработной платы и иных доходов ежемесячно в размере прожиточного минимума");
      const inc = (a.income || []).map(x => ({ salary: "заработная плата", pension: "пенсия", other: "иные доходы" }[x])).filter(Boolean);
      T(`В ${F(a.osp, "отделение")} на исполнении находится ${C.ipLine(a)}, в котором я являюсь должником` + (a.creditor ? `, взыскатель — ${a.creditor}` : "") + ".");
      T(`Я, ${F(a.buyer_name, "ФИО")}, гражданство: ${F(a.citizenship, "гражданство")}, паспорт ${F(a.passport, "паспорт")}, проживаю по адресу: ${F(a.buyer_address, "адрес")}.` + (inc.length ? ` Мои доходы: ${inc.join(", ")}.` : ""));
      const pmText = d.regional
        ? `прожиточного минимума, установленного в субъекте Российской Федерации по месту моего жительства (${F(a.region, "регион")}) для ${GROUP[a.group] || "соответствующей социально-демографической группы населения"}, — ${U.money(d.regional)} руб., поскольку он превышает прожиточный минимум трудоспособного населения в целом по Российской Федерации (${U.money(C.PM.working)} руб. на ${C.PM.year} год)`
        : `прожиточного минимума трудоспособного населения в целом по Российской Федерации (на ${C.PM.year} год — ${U.money(C.PM.working)} руб.), а если прожиточный минимум, установленный в субъекте Российской Федерации по месту моего жительства${a.region ? ` (${a.region})` : ""} для соответствующей социально-демографической группы населения, превышает эту величину, — в размере регионального прожиточного минимума`;
      T(`На основании ч. 5.1 ст. 69 и ч. 1.1 ст. 99 Федерального закона от 02.10.2007 № 229-ФЗ «Об исполнительном производстве» прошу сохранять мою заработную плату и иные доходы ежемесячно в размере ${pmText}.`);
      T(`Доходы в размере прожиточного минимума прошу сохранять на банковском счёте № ${F(a.account ? String(a.account).replace(/\s/g, "") : null, "номер счёта")}, открытом в ${F(a.bank, "банк")}` + (a.bank_address ? `, адрес: ${a.bank_address}` : "") + `, БИК ${F(a.bik, "БИК")}.`);
      T("В связи с этим прошу:");
      [
        "Вынести постановление о сохранении заработной платы и иных доходов ежемесячно в размере прожиточного минимума, а в постановлениях об обращении взыскания на денежные средства на счетах и на заработную плату и иные доходы указать требование об их сохранении в этом размере.",
        "Направить постановления в банк, в котором открыт указанный счёт, а также лицам, выплачивающим мне доходы.",
        "Копию постановления, вынесенного по результатам рассмотрения заявления, направить мне (ч. 7 ст. 64.1 Закона № 229-ФЗ).",
      ].forEach((x, i) => T(`${i + 1}. ${x}`));
      C.attachments(P, ["Копия паспорта.", "Реквизиты банковского счёта (справка банка или выписка из приложения)."].concat((a.income || []).includes("pension") ? ["Справка о размере пенсии."] : []).concat((a.income || []).includes("salary") ? ["Справка о доходах с места работы (при наличии)."] : []));
      C.sign(P, a);
      return P;
    },

    guidance(a, d) {
      return [
        { title: "Подайте через Госуслуги — так быстрее всего.", text: "В разделе исполнительных производств есть заявление о сохранении прожиточного минимума. Можно и лично в отделение (второй экземпляр — с отметкой о приёме) или заказным письмом." },
        { title: "Пристав рассматривает заявление 10 рабочих дней.", text: "Он выносит постановление и направляет его в банк (ч. 5 ст. 64.1 Закона № 229-ФЗ). Не ответил — жалоба старшему приставу (Д-41)." },
        { title: "Сохраняют только на одном счёте.", text: "Переведите зарплату или пенсию на этот счёт. Остальные счета могут оставаться под арестом." },
        { title: "Есть дети или другие иждивенцы?", text: "Сохранить больше прожиточного минимума можно только через суд (ч. 5.2 ст. 69 Закона № 229-ФЗ). Это отдельное заявление в суд, выдавший исполнительный лист." },
        { title: "Пособия на детей, алименты и некоторые другие выплаты списывать нельзя вовсе.", text: "Если их списали — заявление о возврате (Д-40)." },
      ];
    },

    fileName(a) { return "Заявление о сохранении прожиточного минимума" + (a.buyer_name ? " — " + U.shortName(a.buyer_name) : ""); },
  };

  global.DOCS = global.DOCS || {};
  global.DOCS.d38 = spec;
})(typeof window !== "undefined" ? window : globalThis);
